css:
@keyframes shimmer {
  from {
    background-position: 100% 0;
  }

  to {
    background-position: 0 0;
  }
}

.card {
  display: flex;
  gap: 16px;
  max-width: 420px;
  margin: 24px;
  padding: 16px;
  border: 1px solid #e4e4e7;
  border-radius: 12px;
}

.bone {
  border-radius: 6px;
  background-image: linear-gradient(90deg, #e4e4e7 0%, #f4f4f5 50%, #e4e4e7 100%);
  background-size: 300% 100%;
  animation: shimmer 1.4s linear infinite;
}

.avatar {
  flex-shrink: 0;
  width: 48px;
  height: 48px;
  border-radius: 50%;
}

.lines {
  display: grid;
  flex: 1;
  gap: 10px;
}

.line {
  height: 12px;
}

.line-short {
  width: 60%;
}

@media (prefers-reduced-motion: reduce) {
  .bone {
    animation: none;
  }
}
